INSERT INTO collection_pages VALUES('e4583a7a16a85dc748b5b3943b5a298275dbc3b90aa5ee04bf408ac373c5dcc8','9902f5b8ac8e92b4263dc43efa23a7e6ed7fe93138601b4d3ab76ad6f3f63790','{"hasNext":false,"items":[{"author":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"authoredDate":"2026-09-13T18:50:17Z","committedDate":"2026-09-13T18:50:17Z","committer":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"observedAt":"2026-10-09T00:39:40.675Z","repositoryId":1368730048,"sha":"b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a"},{"author":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"authoredDate":"2026-09-13T18:37:52Z","committedDate":"2026-09-13T18:37:52Z","committer":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"observedAt":"2026-10-09T00:39:40.675Z","repositoryId":1368730048,"sha":"723a4ba27da5d4622920a8c93de8236745710394"},{"author":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"authoredDate":"2026-09-13T18:28:11Z","committedDate":"2026-09-13T18:28:11Z","committer":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"observedAt":"2026-10-09T00:39:40.675Z","repositoryId":1368730048,"sha":"f0e68bdae0fafbac22259d25e8cd04157d936a6c"},{"author":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"authoredDate":"2026-09-13T18:25:01Z","committedDate":"2026-09-13T18:25:01Z","committer":{"account":{"login":"mpstaton","providerType":"User"},"email":"mpstaton@gmail.com","name":"mpstaton"},"observedAt":"2026-10-09T00:39:40.675Z","repositoryId":1368730048,"sha":"dc1d9a4dfb249a39c20447be23d2440d0a694c23"}],"observedAt":"2026-10-09T00:39:40.675Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a/comments","commit":{"author":{"date":"2026-09-13T18:50:17Z","email":"mpstaton@gmail.com","name":"mpstaton"},"comment_count":0,"committer":{"date":"2026-09-13T18:50:17Z","email":"mpstaton@gmail.com","name":"mpstaton"},"message":"update(study): add the round-up lists and the commercial-tooling table\n\nTwo additions that widen the study without loosening its question.\n\n\"Lists we liked\" records where several of these references came from. A round-up\nmaps the field faster than enumerating it ourselves, and citing the source beats\nimplying we surveyed it.\n\nThe SaaS table is the more useful one. Specify, zeroheight, Open Design and\nBacklight are solving by product what we are solving by hand, and each answers a\nquestion we actually have. Specify is the commercial answer to what happens to\nplatform tokens once members leave the monorepo and workspace:* stops resolving\nfor a standalone clone. zeroheight treats adoption measurement as a first-class\nfeature, which is our problem too — a registry nobody consumes is a report rather\nthan a system. Backlight is the single-surface authoring workflow that\npackages/gallery is a hand-rolled version of.\n\nStates the standing bias in the README rather than leaving it implicit: we avoid\npaying for things and are attached to rolling our own. The bias is not\nautomatically wrong, since packages/gallery already audits the federal contract\nin a way none of these products can, but naming it makes it re-readable the next\ntime we choose to build over buy.\n\nNotes Storybook in the same breath, and why it is not pinned. It is the\ncategory''s default answer and the gallery is already Storybook-shaped — story to\nfixture, args to controls, docs generated from source. What it cannot do is audit\nF1-F11 from the painted DOM, which is the part worth having. Same stance as the\nkits: steal the conventions, skip the dependency.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"524c682b612968759f51026fe18dadeec380ce43","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/trees/524c682b612968759f51026fe18dadeec380ce43"},"url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/commits/b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a","node_id":"C_kwDOUZUpwNoAKGIxYTdhMzgzNDE0OWZjY2E2YzljMWU4ZGI3OGMxNzZhN2E2M2NiNGE","parents":[{"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/723a4ba27da5d4622920a8c93de8236745710394","sha":"723a4ba27da5d4622920a8c93de8236745710394","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/723a4ba27da5d4622920a8c93de8236745710394"}],"sha":"b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/b1a7a3834149fcca6c9c1e8db78c176a7a63cb4a"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/723a4ba27da5d4622920a8c93de8236745710394/comments","commit":{"author":{"date":"2026-09-13T18:37:52Z","email":"mpstaton@gmail.com","name":"mpstaton"},"comment_count":0,"committer":{"date":"2026-09-13T18:37:52Z","email":"mpstaton@gmail.com","name":"mpstaton"},"message":"update(study): add Carbon as a web-studied reference, not a submodule\n\nCarbon earns study without earning disk. IBM''s system is the most rigorous\npublished example of treating a component API as a documented contract — every\ncomponent ships a prop table, a states matrix and an accessibility statement as\nfirst-class artifacts. That is the discipline our API needs if 1-3 person teams\nare going to code against it after they leave the monorepo.\n\nThe repo is 7.9 GB, a monorepo carrying every framework binding plus decades of\nassets, and none of that is what we came to read. The documentation site is the\nartifact, and it is public.\n\nRenames the section from ''deliberately not pinned'' to ''studied from the web, not\npinned'', because the first framing implied exclusion when the point is the\nopposite — Carbon is in the study, it is just cited rather than cloned. States\nthe rule that falls out: a reference joins the study when it answers the\nquestion, and becomes a submodule only when we need to read its source.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"5b88762d037e0e3ed78cdd3fb516073fbed4dcef","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/trees/5b88762d037e0e3ed78cdd3fb516073fbed4dcef"},"url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/commits/723a4ba27da5d4622920a8c93de8236745710394","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/723a4ba27da5d4622920a8c93de8236745710394","node_id":"C_kwDOUZUpwNoAKDcyM2E0YmEyN2RhNWQ0NjIyOTIwYThjOTNkZTgyMzY3NDU3MTAzOTQ","parents":[{"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/f0e68bdae0fafbac22259d25e8cd04157d936a6c","sha":"f0e68bdae0fafbac22259d25e8cd04157d936a6c","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/f0e68bdae0fafbac22259d25e8cd04157d936a6c"}],"sha":"723a4ba27da5d4622920a8c93de8236745710394","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/723a4ba27da5d4622920a8c93de8236745710394"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/f0e68bdae0fafbac22259d25e8cd04157d936a6c/comments","commit":{"author":{"date":"2026-09-13T18:28:11Z","email":"mpstaton@gmail.com","name":"mpstaton"},"comment_count":0,"committer":{"date":"2026-09-13T18:28:11Z","email":"mpstaton@gmail.com","name":"mpstaton"},"message":"new(study): frontend UI kits and component libraries — ten references pinned\n\nPins the prior art for shipping a component vocabulary to augment-it''s federated\ndesign system. The question is narrower than \"how do UI kits work\": how do they\nname, scale and override component APIs, and which of those conventions survive\ntranslation to Svelte 5 plus CSS custom properties with no Tailwind and no React.\n\nThe stance matters more than the list. We are not adopting a kit. We are deriving\na vocabulary from kits our agents already know, because a foundation model reads\nvariant, size and the -foreground pairing without being taught, and an invented\nsyntax has to be documented before anyone can use it. Deviations get recorded\nrather than hidden.\n\nGrouped by what each reference is actually for. shadcn, Tailwind, MUI and Ant\nsupply vocabulary and scale architecture. shadcn-svelte, Bits and Melt are the\ntranslation proof, since React kits cannot tell us whether the API survives the\nport and we are Svelte 5. Radix is the behaviour reference for the exact ARIA\npatterns the convergence sweep found broken — a role=menu with no menuitem\nchildren, a tablist with no aria-selected. Open Props is the closest\narchitectural precedent, being a complete design system that is nothing but\ncustom properties. Primer is tokens published as a distributable package, which\nis the open question about what our platform packages become once members leave\nthe monorepo and workspace:* stops resolving for a standalone clone.\n\nRecords what was deliberately left out and why. Carbon is 7.9 GB and adds little\nover Primer and MUI at that price. Tailwind Catalyst ships under Tailwind Plus\nand has no public upstream to pin, so saying so beats pinning a lookalike.\n\nCarries one open inquiry rather than a decision: whether Tailwind''s / modifier,\nwhich today means \"this token at N percent\" for opacity, extends to radius and\nspacing. The argument for is that shadcn already computes --radius-sm as\ncalc(--radius * 0.6), so /60 is that same operation exposed at the call site\nrather than a new concept. The argument against is that a pleasant escape hatch\nbecomes the next literal. Left open with both sides and the reading that settles\nit.\n\nmaterial-ui and primer-primitives are --depth 1 at 726 MB and 597 MB full; every\nother reference is a full clone per the sibling studies'' convention.\n\nFiles changed:\n- README.md\n- .gitmodules + 10 gitlinks\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01Qq2Cqf7bXPWT45cfDCYw7C","tree":{"sha":"6549d4d2ec9b71b80fd77a2b3967f70cd965b990","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/trees/6549d4d2ec9b71b80fd77a2b3967f70cd965b990"},"url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/git/commits/f0e68bdae0fafbac22259d25e8cd04157d936a6c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":"https://api.github.com/users/mpstaton/following{/other_user}","gists_url":"https://api.github.com/users/mpstaton/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mpstaton","id":5722,"login":"mpstaton","node_id":"MDQ6VXNlcjU3MjI=","organizations_url":"https://api.github.com/users/mpstaton/orgs","received_events_url":"https://api.github.com/users/mpstaton/received_events","repos_url":"https://api.github.com/users/mpstaton/repos","site_admin":false,"starred_url":"https://api.github.com/users/mpstaton/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mpstaton/subscriptions","type":"User","url":"https://api.github.com/users/mpstaton","user_view_type":"public"},"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/f0e68bdae0fafbac22259d25e8cd04157d936a6c","node_id":"C_kwDOUZUpwNoAKGYwZTY4YmRhZTBmYWZiYWMyMjI1OWQyNWU4Y2QwNDE1N2Q5MzZhNmM","parents":[{"html_url":"https://github.com/lossless-group/study-frontend-ui-kits-component-libraries/commit/dc1d9a4dfb249a39c20447be23d2440d0a694c23","sha":"dc1d9a4dfb249a39c20447be23d2440d0a694c23","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/dc1d9a4dfb249a39c20447be23d2440d0a694c23"}],"sha":"f0e68bdae0fafbac22259d25e8cd04157d936a6c","url":"https://api.github.com/repos/lossless-group/study-frontend-ui-kits-component-libraries/commits/f0e68bdae0fafbac22259d25e8cd04157d936a6c"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/5722?v=4","events_url":"https://api.github.com/users/mpstaton/events{/privacy}","followers_url":"https://api.github.com/users/mpstaton/followers","following_url":