INSERT INTO collection_pages VALUES('4b087a42d9bdd7f86734e9fd43bc6626de21d2ba6e3f76c15c97f37096e594e5','4e7aca75c167727a5139fabb0d0fcf67d5d3d5ff1a8587d911ad05ba22da0663','{"hasNext":false,"items":[{"author":{"account":{"login":"ejfkdev","providerType":"User"},"email":"152914458+ejfkdev@users.noreply.github.com","name":"ejfkdev"},"authoredDate":"2026-09-13T19:59:04Z","committedDate":"2026-09-13T19:59:04Z","committer":{"account":{"login":"ejfkdev","providerType":"User"},"email":"152914458+ejfkdev@users.noreply.github.com","name":"ejfkdev"},"observedAt":"2026-10-09T00:39:43.333Z","repositoryId":1368824244,"sha":"a34a0ffceaa8dae4dc3db9b0c47cb35aa7820e23"}],"observedAt":"2026-10-09T00:39:43.333Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"comments_url":"https://api.github.com/repos/ejfkdev/js-extraction-range/commits/a34a0ffceaa8dae4dc3db9b0c47cb35aa7820e23/comments","commit":{"author":{"date":"2026-09-13T19:59:04Z","email":"152914458+ejfkdev@users.noreply.github.com","name":"ejfkdev"},"comment_count":0,"committer":{"date":"2026-09-13T19:59:04Z","email":"152914458+ejfkdev@users.noreply.github.com","name":"ejfkdev"},"message":"Initial import: JS extraction test range (74 tools x 570 version builds)\n\nA static benchmark range for tools and agents that extract JavaScript from\nwebsites, generated by the dj test harness (real npm install && build per\ntool/version, ground truth derived statically from each build):\n\n- <tool>/<version>/  one independent site per version build (base:\"/\"),\n  with writeup.txt listing every .js as ground truth\n- index.html         catalog table: type / tool / version / homepage /\n                     js total / html-ref / expected / unreferenced\n- 74 tools: 15 bundlers, 17 micro-frontend frameworks, 25 meta/SSR,\n  3 Rust-WASM, 12 admin app templates, es-module-shims + selftest\n- 2,282 source maps included for sourcemap discovery/restoration testing\n- bilingual README (EN/zh-CN), MPL-2.0 LICENSE, .nojekyll for Pages\n- build-machine paths scrubbed: text artifacts made relative, .wasm panic\n  strings replaced length-preservingly; extraction counts re-verified\n  against harness records after scrubbing","tree":{"sha":"2eaa53660af82873ad6ac14e9fde60b320e95e19","url":"https://api.github.com/repos/ejfkdev/js-extraction-range/git/trees/2eaa53660af82873ad6ac14e9fde60b320e95e19"},"url":"https://api.github.com/repos/ejfkdev/js-extraction-range/git/commits/a34a0ffceaa8dae4dc3db9b0c47cb35aa7820e23","verification":{"payload":"tree 2eaa53660af82873ad6ac14e9fde60b320e95e19\nauthor ejfkdev <152914458+ejfkdev@users.noreply.github.com> 1789329544 +0800\ncommitter ejfkdev <152914458+ejfkdev@users.noreply.github.com> 1789329544 +0800\n\nInitial import: JS extraction test range (74 tools x 570 version builds)\n\nA static benchmark range for tools and agents that extract JavaScript from\nwebsites, generated by the dj test harness (real npm install && build per\ntool/version, ground truth derived statically from each build):\n\n- <tool>/<version>/  one independent site per version build (base:\"/\"),\n  with writeup.txt listing every .js as ground truth\n- index.html         catalog table: type / tool / version / homepage /\n                     js total / html-ref / expected / unreferenced\n- 74 tools: 15 bundlers, 17 micro-frontend frameworks, 25 meta/SSR,\n  3 Rust-WASM, 12 admin app templates, es-module-shims + selftest\n- 2,282 source maps included for sourcemap discovery/restoration testing\n- bilingual README (EN/zh-CN), MPL-2.0 LICENSE, .nojekyll for Pages\n- build-machine paths scrubbed: text artifacts made relative, .wasm panic\n  strings replaced length-preservingly; extraction counts re-verified\n  against harness records after scrubbing\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgS5joz/txa9gCHDmkRjODQR26Zj\nxLefxTaIQIownpJgQAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5\nAAAAQAFhgp5nF8mIK5lIkkfj116S0lM0ilo16U+/0BvZZJs3Y7FGbmzFs+pIEsZoSlysJb\n2XMttC3xnD50CWtrw6xQg=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-09-13T20:01:19Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/152914458?v=4","events_url":"https://api.github.com/users/ejfkdev/events{/privacy}","followers_url":"https://api.github.com/users/ejfkdev/followers","following_url":"https://api.github.com/users/ejfkdev/following{/other_user}","gists_url":"https://api.github.com/users/ejfkdev/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ejfkdev","id":152914458,"login":"ejfkdev","node_id":"U_kgDOCR1KGg","organizations_url":"https://api.github.com/users/ejfkdev/orgs","received_events_url":"https://api.github.com/users/ejfkdev/received_events","repos_url":"https://api.github.com/users/ejfkdev/repos","site_admin":false,"starred_url":"https://api.github.com/users/ejfkdev/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ejfkdev/subscriptions","type":"User","url":"https://api.github.com/users/ejfkdev","user_view_type":"public"},"html_url":"https://github.com/ejfkdev/js-extraction-range/commit/